{"files":[{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "林晓曦",
      "role": "protagonist",
      "identity": "体操运动员（重生前是体操教练）",
      "traits": ["坚韧", "善良", "有责任感", "容易自责", "执着"],
      "overt_motivation": "在体操比赛中获得冠军",
      "covert_motivation": "赎罪，弥补前世对队友的伤害",
